anya: JS snippet (will include in PR):
```js
// retry + abort example (fetch + AbortController)
async function callWithRetry(url, opts = {}, maxRetries = 3) {
  let attempt = 0;
  while (attempt <= maxRetries) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), opts.timeout || 5000);
    try {
      const res = await fetch(url, { ...opts, signal: controller.signal });
      clearTimeout(timeout);
      if (res.status === 429) throw new Error('RATE_LIMIT');
      return await res.json();
    } catch (e) {
      clearTimeout(timeout);
      if (e.name === 'AbortError') throw new Error('TIMEOUT');
      attempt += 1;
      if (attempt > maxRetries) throw e;
      // exponential backoff with jitter
      await new Promise(r => setTimeout(r, Math.min(2000, 500 * 2 ** attempt) + Math.random() * 200));
    }
  }
}

// fallback pattern: if retries exhausted, call compact model
async function generateWithFallback(primaryUrl, compactUrl, opts) {
  try {
    return await callWithRetry(primaryUrl, opts);
  } catch (err) {
    if (err.message === 'RATE_LIMIT' || err.message === 'TIMEOUT') {
      // best-effort: try the compact model to stay online
      return await callWithRetry(compactUrl, opts);
    }
    throw err;
  }
}
```
