anya: Python snippet (will include):
```py
import time
import requests

session = requests.Session()

def call_with_retry(url, json, max_retries=3):
    backoff = 0.5
    for i in range(max_retries + 1):
        try:
            r = session.post(url, json=json, timeout=5)
            if r.status_code == 429:
                raise Exception('RATE_LIMIT')
            r.raise_for_status()
            return r.json()
        except Exception as e:
            if i == max_retries:
                raise
            time.sleep(min(2.0, backoff * (2 ** i)))

# fallback to cached response
def generate_with_cache(primary_url, compact_url, payload, cache):
    try:
        return call_with_retry(primary_url, payload)
    except Exception:
        if 'last_good' in cache:
            return cache['last_good']
        return call_with_retry(compact_url, payload)
```
